+    @Override
+    public int hashCode() {
+        return Objects.hash(inputType, returnToken);
+    }
+
+    public static String invalidInputTypeMessage(InputType inputType) {
+        return Strings.format("received invalid input type value [%s]", inputType.toString());
+    }
